def f(text):
    count = len(text)
    for i in range(-count+1, 0):
        text = text + text[i]
        if i == -count + 2:
            return text
    return text

def f(n):
    p = ''
    if n%2 == 1:
        p+='sn'
    else:
        return n*n
    for x in range(1, n+1):
        if x%2 == 0:
            p+='to'
        else:
            p+='ts'
        return p

def f(text, dng):
    if dng not in text:
        return text
    if text[-len(dng):] == dng:
        return text[:-len(dng)]
    return text[:-1] + f(text[:-2], dng)
